-- IPA 2020-06-14 questions 31-40: source-reviewed adaptations; q33 and q35 reuse 2022 and 2019 canonical questions.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20200614-q31','exam-fe','OSIネットワーク層','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問31・改編】OSI基本参照モデルのネットワーク層の役割として適切なものはどれか。','[{"id":"a","text":"エンドシステム間の通信のため経路選択や中継を行う"},{"id":"b","text":"利用者に近い層でファイル転送や電子メールを提供する"},{"id":"c","text":"物理媒体の違いを吸収し上位層に伝送路を提供する"},{"id":"d","text":"隣接ノード間で誤り検出や再送制御を行う"}]','"a"','ネットワーク層は経路選択とパケットの中継を担う。隣接ノード間の制御はデータリンク層。中文：网络层负责路径选择和分组转发；相邻节点间控制属于数据链路层。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q32','exam-fe','リピータ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問32・改編】LANの伝送距離を延ばすため、途中で信号波形を増幅・整形し物理層で中継する装置はどれか。','[{"id":"a","text":"レイヤ2スイッチ"},{"id":"b","text":"ブリッジ"},{"id":"c","text":"リピータ"},{"id":"d","text":"ルータ"}]','"c"','リピータは物理層で信号を再生・中継する。ブリッジやスイッチは主にデータリンク層、ルータはネットワーク層で動作する。中文：中继器在物理层再生信号，延长传输距离。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q34','exam-fe','MIME','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問34・改編】電子メールで画像、動画、音声など多様な情報を送るための仕組みはどれか。','[{"id":"a","text":"FTP"},{"id":"b","text":"MIME"},{"id":"c","text":"POP"},{"id":"d","text":"TELNET"}]','"b"','MIMEはメールの内容形式や符号化を拡張し、画像などを扱えるようにする。中文：MIME扩展邮件内容格式和编码，使邮件可以包含图片、音视频等。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q36','exam-fe','DNSキャッシュポイズニング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問36・改編】社内外の名前解決に共用するDNSサーバがキャッシュポイズニングを受けた場合、直接起こり得る現象はどれか。','[{"id":"a","text":"DNSサーバ名がディスク上で書き換えられ接続できなくなる"},{"id":"b","text":"DNSサーバ内のワームが問合せ元に不正プログラムを送る"},{"id":"c","text":"社内メールの宛先アドレスが書き換えられ送信できなくなる"},{"id":"d","text":"社内利用者が特定のWebサイトにアクセスすると本来と異なるサーバに誘導される"}]','"d"','偽の名前解決結果がキャッシュされると、利用者は意図しないIPアドレスへ誘導され得る。中文：DNS缓存被注入虚假记录后，用户可能被引导到错误的网站。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q37','exam-fe','ソーシャルエンジニアリング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問37・改編】ソーシャルエンジニアリングに分類される手口はどれか。','[{"id":"a","text":"ウイルスが作ったバックドアから侵入する"},{"id":"b","text":"管理者を装い利用者に問い合わせてパスワードを聞き出す"},{"id":"c","text":"総当たりツールでパスワードを解析する"},{"id":"d","text":"バッファオーバフローを利用して侵入する"}]','"b"','人の心理や信頼を悪用して秘密を聞き出す手口がソーシャルエンジニアリング。中文：冒充管理员诱使用户透露密码，是利用人的信任进行攻击。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q38','exam-fe','パスワード再設定','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問38・改編】Webシステムでパスワードを忘れた利用者が合い言葉に正しく答えた後の処理として、次のうち最も適切なものはどれか。','[{"id":"a","text":"登録済みメールアドレスに現在のパスワードを送る"},{"id":"b","text":"登録済みメールアドレスに推測困難な再設定用URLを送る"},{"id":"c","text":"新たに入力されたメールアドレスに現在のパスワードを送る"},{"id":"d","text":"新たに入力されたメールアドレスに推測困難な再設定用URLを送る"}]','"b"','既に登録済みの宛先を使い現在のパスワードを送らず再設定する。実運用ではURLの短い有効期限と一回限りの利用なども必要。中文：向预先登记的邮箱发送难以猜测的重置链接，不发送现有密码；实际系统还应设置短时有效和一次性使用。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q39','exam-fe','メッセージ認証符号','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問39・改編】メッセージ認証符号（MAC）の利用目的はどれか。','[{"id":"a","text":"メッセージが改ざんされていないことを確認する"},{"id":"b","text":"メッセージの暗号化方式を確認する"},{"id":"c","text":"メッセージの概要を確認する"},{"id":"d","text":"メッセージの秘匿性を確保する"}]','"a"','MACは共有鍵を用いて完全性と送信元の正当性を確認する。暗号化とは異なり内容の秘匿は行わない。中文：消息认证码利用共享密钥验证完整性和发送方真实性，本身不负责保密。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q40','exam-fe','ハイブリッド暗号','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問40・改編】OpenPGPやS/MIMEで用いられるハイブリッド暗号方式の特徴はどれか。','[{"id":"a","text":"IPsecとTLSを選択可能にして利便性を高める"},{"id":"b","text":"公開鍵暗号と共通鍵暗号を組み合わせ鍵管理と処理性能の両立を図る"},{"id":"c","text":"複数の共通鍵暗号を組み合わせて処理性能を高める"},{"id":"d","text":"複数の公開鍵暗号を組み合わせて安全性を高める"}]','"b"','データは高速な共通鍵暗号で暗号化し、その共通鍵を公開鍵暗号で保護する。中文：用对称密钥加密数据，再用公钥加密保护对称密钥。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption');
